package net.officefloor.hq.app.period;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.session.CurrentUser;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/sheets/{sheetId}/periods")
@Validated
public class PeriodController {

    /** A period as the screen shows it: whether it is closed, the due-total fixed when it was
     *  closed (null while open), and each person's due-total for it fixed then, by person id
     *  (empty while open). */
    public record PeriodView(long id, String name, LocalDate from, LocalDate to, boolean closed, String closedTotal,
            Map<Long, String> closedPersonTotals) {
        static PeriodView of(Period p) {
            Map<Long, String> personTotals = new LinkedHashMap<>();
            p.getClosedPersonTotals().forEach((id, total) -> personTotals.put(id, total.setScale(2).toPlainString()));
            return new PeriodView(p.getId(), p.getName(), p.getFrom(), p.getTo(), p.isClosed(),
                    p.getClosedTotal() == null ? null : p.getClosedTotal().setScale(2).toPlainString(), personTotals);
        }
    }

    /** A period as the form submits it: a name without spaces, an optional from-date (the sheet's
     *  today when absent) and a to-date. */
    public record PeriodForm(
            @NotBlank @Size(max = 100) @Pattern(regexp = "\\s*\\S+\\s*") String name,
            LocalDate from,
            @NotNull LocalDate to) {
    }

    private final PeriodService service;

    public PeriodController(PeriodService service) {
        this.service = service;
    }

    @GetMapping
    public List<PeriodView> list(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "\\S+") String sheetId,
            @RequestHeader(CurrentUser.HEADER) @NotBlank @Size(max = 100) String user) {
        return service.list(sheetId).stream().map(PeriodView::of).toList();
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public PeriodView add(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "\\S+") String sheetId,
            @RequestHeader(CurrentUser.HEADER) @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody PeriodForm body) {
        return PeriodView.of(service.add(sheetId, user.trim(), body.name(), body.from(), body.to()));
    }

    @PostMapping("/{id}/close")
    public PeriodView close(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "\\S+") String sheetId,
            @PathVariable long id,
            @RequestHeader(CurrentUser.HEADER) @NotBlank @Size(max = 100) String user) {
        return PeriodView.of(service.close(sheetId, user.trim(), id));
    }

    @PostMapping("/{id}/reopen")
    public PeriodView reopen(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "\\S+") String sheetId,
            @PathVariable long id,
            @RequestHeader(CurrentUser.HEADER) @NotBlank @Size(max = 100) String user) {
        return PeriodView.of(service.reopen(sheetId, user.trim(), id));
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.Comparator;
import java.util.List;
import java.util.Optional;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.settings.Permission;
import net.officefloor.hq.app.settings.SettingsService;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetService;
import net.officefloor.hq.app.sheet.TodayChanged;
import org.springframework.context.event.EventListener;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class PeriodService {

    private final PeriodRepository periods;
    private final SheetService sheets;
    private final RollupService rollup;
    private final SettingsService settings;
    private final Audit audit;

    public PeriodService(PeriodRepository periods, SheetService sheets, RollupService rollup, SettingsService settings,
            Audit audit) {
        this.periods = periods;
        this.sheets = sheets;
        this.rollup = rollup;
        this.settings = settings;
        this.audit = audit;
    }

    @Transactional(readOnly = true)
    public List<Period> list(String sheetId) {
        return periods.findBySheetIdOrderByFromAsc(sheetId);
    }

    /** Add a period to the sheet (the sheet is created first if it was never loaded; a from-date left out is the sheet's today); refused when
     *  its from-date is after its to-date, its name is in use on the sheet or it overlaps another. */
    @Transactional
    public Period add(String sheetId, String user, String name, LocalDate fromOrNull, LocalDate to) {
        sheets.load(sheetId, user);
        LocalDate from = fromOrNull != null ? fromOrNull : sheets.today(sheetId);
        // held until the transaction ends, so two periods added at once are checked one after the other
        sheets.lock(sheetId);
        String trimmed = name.trim();
        if (from.isAfter(to)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The from-date is after the to-date");
        }
        List<Period> existing = periods.findBySheetIdOrderByFromAsc(sheetId);
        if (existing.stream().anyMatch(p -> p.getName().equalsIgnoreCase(trimmed))) {
            throw nameInUse();
        }
        if (existing.stream().anyMatch(p -> p.overlaps(from, to))) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The period overlaps another");
        }
        Period period;
        try {
            period = periods.saveAndFlush(new Period(sheetId, trimmed, from, to));
        } catch (DataIntegrityViolationException e) {
            throw nameInUse();
        }
        audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user
                + " period=" + trimmed + " from=" + from + " to=" + to);
        return period;
    }

    /** Close a period, fixing each person's due-total for it, and its own (their sum), at the
     *  figures they show now; refused (403) when the user's role may not close by the sheet's
     *  permission matrix, and (409) when it is already closed. */
    @Transactional
    public Period close(String sheetId, String user, long id) {
        // held until the transaction ends, so no claim in the period changes while it is closed
        sheets.lock(sheetId);
        Period period = periods.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period"));
        settings.refuseUnlessAllowed(sheetId, user, Permission.CLOSE);
        if (period.isClosed()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The period is already closed");
        }
        closeNow(sheetId, user, period, "");
        return period;
    }

    /** Once the sheet's today changes, close every open period whose to-date plus the sheet's
     *  grace days (when set) is before the new today, in order of their to-dates, each as a close
     *  by hand would. */
    @EventListener
    @Transactional
    public void closePastGrace(TodayChanged change) {
        Integer graceDays = sheets.find(change.sheetId()).map(Sheet::getGraceDays).orElse(null);
        if (graceDays == null) {
            return;
        }
        periods.findBySheetIdOrderByFromAsc(change.sheetId()).stream()
                .filter(p -> !p.isClosed() && p.getTo().plusDays(graceDays).isBefore(change.today()))
                .sorted(Comparator.comparing(Period::getTo))
                .forEach(p -> closeNow(change.sheetId(), change.user(), p, " auto=yes"));
    }

    /** Fix the period's figures as they show now and audit it, with any trailing fields. */
    private void closeNow(String sheetId, String user, Period period, String trailing) {
        period.close(rollup.dueByPersonBetween(sheetId, period.getFrom(), period.getTo()));
        periods.flush();
        BigDecimal total = period.getClosedTotal();
        audit.recordOnCommit("PERIOD_CLOSED sheet=" + sheetId + " by=" + user
                + " period=" + period.getName() + " total=" + total.toPlainString() + trailing);
    }

    /** Reopen a closed period, its due-total live again; refused (403) unless the user's role may
     *  reopen by the sheet's permission matrix (by default a steward), and (409) when it is not closed. */
    @Transactional
    public Period reopen(String sheetId, String user, long id) {
        sheets.lock(sheetId);
        Period period = periods.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period"));
        settings.refuseUnlessAllowed(sheetId, user, Permission.REOPEN);
        if (!period.isClosed()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The period is not closed");
        }
        period.reopen();
        periods.flush();
        audit.recordOnCommit("PERIOD_REOPENED sheet=" + sheetId + " by=" + user + " period=" + period.getName());
        return period;
    }

    /** The sheet's period whose dates contain {@code date}, if any. */
    @Transactional(readOnly = true)
    public Optional<Period> containing(String sheetId, LocalDate date) {
        return periods.findBySheetIdOrderByFromAsc(sheetId).stream().filter(p -> p.contains(date)).findFirst();
    }

    /** Refuse (423) a change to a claim dated {@code date} when a closed period contains it. */
    @Transactional(readOnly = true)
    public void refuseIfClosed(String sheetId, LocalDate date) {
        periods.findBySheetIdOrderByFromAsc(sheetId).stream()
                .filter(p -> p.isClosed() && p.contains(date))
                .findFirst()
                .ifPresent(p -> {
                    throw new ResponseStatusException(HttpStatus.LOCKED,
                            "The claim's date is in closed period " + p.getName());
                });
    }

    private static ResponseStatusException nameInUse() {
        return new ResponseStatusException(HttpStatus.CONFLICT, "The period name is in use on the sheet");
    }
}
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session, otherError } from '../../core/session';
import { cents } from '../claims/claims-api';

export interface Period {
  id: number;
  name: string;
  /** The first date (yyyy-mm-dd) of the period, inclusive. */
  from: string;
  /** The last date (yyyy-mm-dd) of the period, inclusive. */
  to: string;
  closed: boolean;
  /** The due-total fixed when the period was closed (two decimals); null while open. */
  closedTotal: string | null;
  /** Each person's due-total for the period fixed when it was closed (two decimals), by person
   *  id; empty while open. */
  closedPersonTotals: Record<string, string>;
}

/** The period whose dates contain a date (yyyy-mm-dd), or null when none does. */
export function periodOn(periods: readonly Period[], date: string): Period | null {
  return periods.find((p) => p.from <= date && date <= p.to) ?? null;
}

/** The due-total a period shows, in cents: the sum of the people's due-totals for it, from
 *  dueTotals (by period id; 0 with none). */
export function periodDueCents(p: Period, dueTotals: ReadonlyMap<number, number>): number {
  return dueTotals.get(p.id) ?? 0;
}

/** The due-total a person shows for a period, in cents: the one fixed when it was closed (0 for a
 *  person added since), else the live one from dueTotals (by period id; 0 with none). */
export function personPeriodDueCents(p: Period, personId: number, dueTotals: ReadonlyMap<number, number>): number {
  if (p.closed) {
    const fixed = p.closedPersonTotals?.[personId];
    return fixed === undefined ? 0 : cents(fixed);
  }
  return dueTotals.get(p.id) ?? 0;
}

// The sheet's periods, read and written through the server.
@Injectable({ providedIn: 'root' })
export class PeriodsApi {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  list(sheetId: string): Promise<Period[]> {
    return firstValueFrom(this.http.get<Period[]>(this.url(sheetId), { headers: this.headers() }));
  }

  add(sheetId: string, name: string, from: string, to: string): Promise<Period> {
    return firstValueFrom(this.http.post<Period>(this.url(sheetId), { name, from, to }, { headers: this.headers() }));
  }

  close(sheetId: string, id: number): Promise<Period> {
    return firstValueFrom(this.http.post<Period>(`${this.url(sheetId)}/${id}/close`, null, { headers: this.headers() }));
  }

  reopen(sheetId: string, id: number): Promise<Period> {
    return firstValueFrom(this.http.post<Period>(`${this.url(sheetId)}/${id}/reopen`, null, { headers: this.headers() }));
  }

  private url(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}/periods`;
  }

  private headers(): Record<string, string> {
    return { 'X-User': this.session.user() ?? '' };
  }
}

export function periodError(e: unknown): string {
  if (e instanceof HttpErrorResponse && e.status === 400) return 'Enter a name without spaces and a from-date on or before the to-date, as yyyy-mm-dd.';
  if (e instanceof HttpErrorResponse && e.status === 409) return 'The name is in use on the sheet, or the dates overlap another period.';
  return otherError(e);
}

export function closeError(e: unknown): string {
  if (e instanceof HttpErrorResponse && e.status === 403) return 'Your role may not close a period.';
  if (e instanceof HttpErrorResponse && e.status === 409) return 'The period is already closed.';
  if (e instanceof HttpErrorResponse && e.status === 404) return 'That period is no longer on this sheet.';
  return otherError(e);
}

export function reopenError(e: unknown): string {
  if (e instanceof HttpErrorResponse && e.status === 403) return 'Your role may not reopen a period.';
  if (e instanceof HttpErrorResponse && e.status === 409) return 'The period is not closed.';
  if (e instanceof HttpErrorResponse && e.status === 404) return 'That period is no longer on this sheet.';
  return otherError(e);
}
import { Component, inject, input, output, signal } from '@angular/core';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { Session } from '../../core/session';
import { money } from '../claims/claims-api';
import { Period, PeriodsApi, closeError, periodDueCents, periodError, reopenError } from './periods-api';

const DATE = /^\d{4}-\d{2}-\d{2}$/;

// The sheet's periods, by from-date, each with its due-total and whether it is closed (with the
// buttons that close and reopen it), and the form that adds a period.
@Component({
  selector: 'app-periods',
  imports: [ReactiveFormsModule],
  template: `
    <section aria-labelledby="periods-heading">
      <h2 id="periods-heading">Periods</h2>
      <form [formGroup]="form" (ngSubmit)="submit()" aria-label="Add period">
        <label for="period-form-name">Name</label>
        <input id="period-form-name" data-testid="period-form-name" formControlName="name" autocomplete="off" />
        <label for="period-form-from">From</label>
        <input id="period-form-from" type="date" data-testid="period-form-from" formControlName="from" />
        <label for="period-form-to">To</label>
        <input id="period-form-to" type="date" data-testid="period-form-to" formControlName="to" />
        <button type="submit" data-testid="period-form-submit">Add period</button>
        @if (error(); as err) {
          <p role="alert" data-testid="period-form-error">{{ err }}</p>
        }
      </form>
      <table data-testid="periods-list">
        <thead>
          <tr><th scope="col">Name</th><th scope="col">From</th><th scope="col">To</th><th scope="col">Due</th><th scope="col">Closed</th><th scope="col"><span class="visually-hidden">Actions</span></th></tr>
        </thead>
        <tbody>
          @for (p of periods(); track p.id) {
            <tr [attr.data-testid]="'period-row-' + p.name">
              <th scope="row" data-testid="period-name">{{ p.name }}</th>
              <td data-testid="period-from">{{ p.from }}</td>
              <td data-testid="period-to">{{ p.to }}</td>
              <td data-testid="period-due-total">{{ dueOf(p) }}</td>
              <td data-testid="period-closed">{{ p.closed ? 'yes' : 'no' }}</td>
              <td>
                <button type="button" data-testid="period-close" (click)="close(p)"
                  [attr.aria-label]="'Close period ' + p.name">Close</button>
                <button type="button" data-testid="period-reopen" (click)="reopen(p)"
                  [attr.aria-label]="'Reopen period ' + p.name">Reopen</button>
                @if (rowErrors()[p.id]; as err) {
                  <p role="alert" data-testid="period-error">{{ err }}</p>
                }
              </td>
            </tr>
          }
        </tbody>
      </table>
    </section>
  `,
})
export class Periods {
  private readonly session = inject(Session);
  private readonly api = inject(PeriodsApi);

  /** The sheet's periods, by from-date. */
  readonly periods = input.required<Period[]>();
  /** Each period's due-total in cents, by period id. */
  readonly dueTotals = input.required<Map<number, number>>();
  /** A period just added or closed, for the sheet to take in. */
  readonly saved = output<Period>();

  protected readonly error = signal<string | null>(null);
  /** The error of each period's last refused action, by period id. */
  protected readonly rowErrors = signal<Record<number, string>>({});
  /** Whether a submit is waiting for its answer; a second submit meanwhile is ignored. */
  private submitting = false;

  protected readonly form = new FormGroup({
    name: new FormControl('', { nonNullable: true }),
    from: new FormControl('', { nonNullable: true }),
    to: new FormControl('', { nonNullable: true }),
  });

  constructor() {
    this.form.valueChanges.subscribe(() => this.error.set(null));
  }

  /** A closed period shows the due-total fixed when it was closed; an open one its live total. */
  protected dueOf(p: Period): string {
    return money(periodDueCents(p, this.dueTotals()));
  }

  /** Close a period, fixing its due-total; a refusal shows an error on the period. */
  protected async close(p: Period): Promise<void> {
    this.rowErrors.update(({ [p.id]: _, ...rest }) => rest);
    const sheetId = this.session.sheetId();
    if (!sheetId) return;
    try {
      const closed = await this.api.close(sheetId, p.id);
      if (this.session.sheetId() === sheetId) this.saved.emit(closed);
    } catch (e) {
      this.rowErrors.update((errs) => ({ ...errs, [p.id]: closeError(e) }));
    }
  }

  /** Reopen a closed period, its due-total live again; a refusal shows an error on the period. */
  protected async reopen(p: Period): Promise<void> {
    this.rowErrors.update(({ [p.id]: _, ...rest }) => rest);
    const sheetId = this.session.sheetId();
    if (!sheetId) return;
    try {
      const reopened = await this.api.reopen(sheetId, p.id);
      if (this.session.sheetId() === sheetId) this.saved.emit(reopened);
    } catch (e) {
      this.rowErrors.update((errs) => ({ ...errs, [p.id]: reopenError(e) }));
    }
  }

  protected async submit(): Promise<void> {
    if (this.submitting) return;
    this.error.set(null);
    const sheetId = this.session.sheetId();
    if (!sheetId) return;
    const name = this.form.controls.name.value.trim();
    const from = this.form.controls.from.value.trim() || (this.session.today() ?? '');
    const to = this.form.controls.to.value.trim();
    if (!/^\S+$/.test(name)) {
      this.error.set('Enter a name without spaces.');
      return;
    }
    if (!DATE.test(from) || !DATE.test(to)) {
      this.error.set('Enter a from-date and a to-date as yyyy-mm-dd.');
      return;
    }
    if (from > to) {
      this.error.set('The from-date must be on or before the to-date.');
      return;
    }
    if (this.periods().some((p) => p.name.toLowerCase() === name.toLowerCase())) {
      this.error.set('The name is in use on the sheet.');
      return;
    }
    const overlapping = this.periods().find((p) => p.from <= to && from <= p.to);
    if (overlapping) {
      this.error.set(`The dates overlap period ${overlapping.name}.`);
      return;
    }
    this.submitting = true;
    try {
      const period = await this.api.add(sheetId, name, from, to);
      if (this.session.sheetId() === sheetId) this.saved.emit(period);
      this.form.reset({ name: '', from: '', to: '' }, { emitEvent: false });
    } catch (e) {
      this.error.set(periodError(e));
    } finally {
      this.submitting = false;
    }
  }
}
