    const sheetId = this.session.sheetId();
    if (!sheetId) return;
    const from = this.generateForm.controls.from.value.trim() || (this.session.today() ?? '');
    const to = this.generateForm.controls.to.value.trim();
    if (!DATE.test(from) || !DATE.test(to)) {
